  const DESTROYED: CombatEvent = {
    kind: 'destroyed',
    target: 'ship-p2',
    source: { kind: 'player', id: 'p1' },
    weapon: 'laser',
  };

  it("a 'destroyed' event at a known target plays the EXPLOSION (not a small impact flash) + a 6 px shake", () => {
    const { world, explosion, impact, shake } = fxSpy();
